#!/usr/bin/env bash
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# Mirror the repo sources into .tools/src-mirror and adapt the two source
# artifacts that only MSVC's own toolchain accepts:
#
#   1. PIMETextService/resource.h is stored as UTF-16LE with a BOM. MSVC's
#      cl.exe accepts UTF-16 input; clang-cl does not (it only reads UTF-8).
#   2. PIMETextService/PIMEClient.cpp calls std::transform(..., tolower).
#      MSVC's <locale> injects an extra std::tolower overload set, so the
#      unqualified name is ambiguous under clang; MSVC's compiler picks the
#      C `tolower` overload.
#
# The mirror is a build-time artifact only: the upstream checkout is never
# modified. Regenerate it after any source change.
#
# Staleness is detected over the WHOLE mirrored tree, not a hand-picked list
# of files. An earlier version watched only PIMEClient.cpp, resource.h and
# CMakeLists.txt, so editing any other mirrored source silently built the
# previous revision instead of the current one - a wrong-result bug with no
# error message. The manifest below records every mirrored file's size and
# mtime, so any change under a mirrored tree invalidates the mirror.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="$ROOT/.tools/src-mirror"
MANIFEST="$ROOT/.tools/src-mirror.manifest"

# Directories mirrored wholesale, and single files copied verbatim.
# PIMELauncher is needed too: the root CMakeLists.txt adds it as a
# subdirectory for the 32-bit build, so without it CMake fails to configure.
MIRROR_DIRS=(PIMETextService libIME2 json tests PIMELauncher)
MIRROR_FILES=(CMakeLists.txt version.txt)

# Never mirrored: VCS metadata and dependency trees the C++ build never reads.
PRUNE_NAMES=(.git node_modules __pycache__ target)

# A stable fingerprint of everything the mirror is built from. Cheap enough
# to run on every build (a few hundred files) and sensitive to every change
# that matters: content edits change the mtime, added or removed files change
# the listing.
compute_manifest() {
  local rel
  {
    for rel in "${MIRROR_DIRS[@]}"; do
      [[ -d "$ROOT/$rel" ]] || continue
      find "$ROOT/$rel" -type d \( -name .git -o -name node_modules \
        -o -name __pycache__ -o -name target \) -prune -o \
        -type f -printf '%p\t%s\t%T@\n' 2>/dev/null
    done
    for rel in "${MIRROR_FILES[@]}"; do
      [[ -f "$ROOT/$rel" ]] || continue
      find "$ROOT/$rel" -type f -printf '%p\t%s\t%T@\n' 2>/dev/null
    done
  } | sed "s|^$ROOT/||" | LC_ALL=C sort
}

# The manifest must cover exactly what copy_tree copies, or the two disagree
# about what "up to date" means.

manifest_is_current() {
  [[ -d "$SRC" && -f "$MANIFEST" ]] || return 1
  local current
  current="$(compute_manifest)"
  [[ "$current" == "$(cat "$MANIFEST")" ]]
}

if manifest_is_current; then
  echo "==> mirror up to date: $SRC"
  exit 0
fi

echo "==> refreshing source mirror: $SRC"
rm -rf "$SRC"
mkdir -p "$SRC"

copy_tree() {
  local rel="$1"
  [[ -d "$ROOT/$rel" ]] || return 0
  mkdir -p "$SRC/$rel"
  # Copy with the excluded directories left out rather than copied and then
  # deleted: PIMELauncher/target holds ~900MB of Cargo build output, and
  # copying it only to remove it again is pure waste.
  local exclude=()
  local name
  for name in "${PRUNE_NAMES[@]}"; do
    exclude+=("--exclude=./$name" "--exclude=*/$name")
  done
  tar -cf - "${exclude[@]}" -C "$ROOT/$rel" . | tar -xf - -C "$SRC/$rel"
}

for rel in "${MIRROR_DIRS[@]}"; do
  copy_tree "$rel"
done
for rel in "${MIRROR_FILES[@]}"; do
  [[ -f "$ROOT/$rel" ]] && cp "$ROOT/$rel" "$SRC/$rel"
done

# 1. resource.h: UTF-16LE -> UTF-8 (no BOM).
RH="$SRC/PIMETextService/resource.h"
if [[ -f "$RH" && "$(head -c 2 "$RH" | od -An -tx1 | tr -d ' \n')" == "fffe" ]]; then
  echo "==> converting resource.h from UTF-16LE to UTF-8"
  iconv -f UTF-16LE -t UTF-8 "$RH" | sed '1s/^\xEF\xBB\xBF//' > "$RH.utf8"
  mv "$RH.utf8" "$RH"
fi
if [[ -f "$RH" && "$(head -c 2 "$RH" | od -An -tx1 | tr -d ' \n')" == "fffe" ]]; then
  echo "ERROR: resource.h is still UTF-16" >&2
  exit 1
fi

# 2. PIMEClient.cpp: disambiguate the tolower overload set.
PC="$SRC/PIMETextService/PIMEClient.cpp"
if [[ -f "$PC" ]] && grep -q "result.end(), result.begin(), tolower)" "$PC"; then
  echo "==> disambiguating tolower in PIMEClient.cpp"
  sed -i 's|transform(result.begin(), result.end(), result.begin(), tolower);|transform(result.begin(), result.end(), result.begin(), [](char c) { return (char)::tolower((unsigned char)c); });|' "$PC"
fi
if [[ -f "$PC" ]] && ! grep -q "::tolower((unsigned char)c)" "$PC" &&
   grep -q "result.end(), result.begin(), tolower)" "$PC"; then
  echo "ERROR: tolower disambiguation did not apply" >&2
  exit 1
fi

compute_manifest > "$MANIFEST"
echo "==> mirror ready"
